//! Barycentric weights indexed by the Kimberling center number.

use std::f64::consts::PI;

fn power(base: f64, exponent: f64) -> f64 {
    base.powf(exponent)
}

pub(super) fn weight(k: i32, a: f64, b: f64, c: f64) -> f64 {
    if (2923..=2928).contains(&k) {
        let [x, y, z] = [
            weight(k - 2910, a, b, c),
            weight(k - 2910, b, c, a),
            weight(k - 2910, c, a, b),
        ];
        // The recursive calls leave the upstream powers in the order (c, a, b).
        let c2 = c * c;
        return c2
            * (-(c * c2) / (c * y + b * z)
                + (a * (a * a)) / (a * z + c * x)
                + (b * (b * b)) / (b * x + a * y));
    }
    match k {
        0..=99 => weights_0(k, a, b, c),
        100..=199 => weights_100(k, a, b, c),
        200..=299 => weights_200(k, a, b, c),
        300..=399 => weights_300(k, a, b, c),
        400..=499 => weights_400(k, a, b, c),
        500..=599 => weights_500(k, a, b, c),
        600..=699 => weights_600(k, a, b, c),
        700..=799 => weights_700(k, a, b, c),
        800..=899 => weights_800(k, a, b, c),
        900..=999 => weights_900(k, a, b, c),
        1000..=1099 => weights_1000(k, a, b, c),
        1100..=1199 => weights_1100(k, a, b, c),
        1200..=1299 => weights_1200(k, a, b, c),
        1300..=1399 => weights_1300(k, a, b, c),
        1400..=1499 => weights_1400(k, a, b, c),
        1500..=1599 => weights_1500(k, a, b, c),
        1600..=1699 => weights_1600(k, a, b, c),
        1700..=1799 => weights_1700(k, a, b, c),
        1800..=1899 => weights_1800(k, a, b, c),
        1900..=1999 => weights_1900(k, a, b, c),
        2000..=2099 => weights_2000(k, a, b, c),
        2100..=2199 => weights_2100(k, a, b, c),
        2200..=2299 => weights_2200(k, a, b, c),
        2300..=2399 => weights_2300(k, a, b, c),
        2400..=2499 => weights_2400(k, a, b, c),
        2500..=2599 => weights_2500(k, a, b, c),
        2600..=2699 => weights_2600(k, a, b, c),
        2700..=2799 => weights_2700(k, a, b, c),
        2800..=2899 => weights_2800(k, a, b, c),
        2900..=2999 => weights_2900(k, a, b, c),
        3000..=3099 => weights_3000(k, a, b, c),
        _ => f64::NAN,
    }
}

